bash_wrappers.command:
python3 -c 'import json,os,stat,subprocess; q="evidence://campaign"; s=json.load(open(q+"/scopes/heldout.json")); print("OUTPUT",os.path.realpath(q+"/advisories/heldout-b")); print("PROJECT",subprocess.run(["git","--no-pager","-C","checkout://trusted-product","rev-parse","HEAD"],capture_output=True,text=True).stdout.strip());
for r in s["records"]:
 print(r["id"], "root_real",os.path.realpath(r["root"]));
 for args in (["rev-parse","HEAD","HEAD^{tree}"],["status","--porcelain=v1","--untracked-files=no"]):
  p=subprocess.run(["git","--no-pager","--no-optional-locks","-C",r["root"]]+args,capture_output=True,text=True); print(args,p.returncode,repr(p.stdout),repr(p.stderr))
 for f in r["production_files"]+r["immediate_caller_or_helper_files"]+r["configuration_files"]+r["test_or_requirement_files"]:
  p=r["root"]+"/"+f; m=os.lstat(p); print(f,"regular",stat.S_ISREG(m.st_mode),"bytes",m.st_size,"parent_real",os.path.realpath(os.path.dirname(p)))'

python3 -c 'import os,stat; q="evidence://campaign";
for p in [q,q+"/advisories",q+"/advisories/heldout-b",q+"/locked",q+"/locked/proof-readiness",q+"/targets/H1",q+"/targets/H2/src",q+"/targets/H2/src/blinker",q+"/targets/H2/tests",q+"/targets/H3/src",q+"/targets/H3/test"]:
 try:
  m=os.lstat(p); print(p,"symlink",stat.S_ISLNK(m.st_mode),"directory",stat.S_ISDIR(m.st_mode))
 except FileNotFoundError: print(p,"absent")'

python3 -c 'import json,subprocess; q="evidence://campaign";
for r in json.load(open(q+"/scopes/heldout.json"))["records"]:
 for args in (["rev-parse","HEAD","HEAD^{tree}"],["status","--porcelain=v1","--untracked-files=no"]):
  p=subprocess.run(["git","--no-pager","--no-optional-locks","-C",r["root"]]+args,capture_output=True,text=True); print(r["id"],args,p.returncode,repr(p.stdout),repr(p.stderr))'

python3 -c 'import hashlib,json,os; q="evidence://campaign";
for slot in ["H1","H2","H3"]:
 p=q+"/advisories/heldout-b/"+slot+"/assessment.md"; b=open(p,"rb").read(); print(json.dumps({"slot":slot,"path":p,"sha256":hashlib.sha256(b).hexdigest(),"bytes":len(b)}))
p=q+"/locked/proof-readiness/SKILL.md"; b=open(p,"rb").read(); print("SKILL",hashlib.sha256(b).hexdigest(),len(b))'

final_data_check.command:
python3 -c 'import json,hashlib; p="evidence://campaign/advisories/heldout-b/RESULT.json"; b=open(p,"rb").read(); r=json.loads(b);
for a in r["artifacts"]:
 d=open(a["path"],"rb").read(); assert len(d)==a["bytes"] and hashlib.sha256(d).hexdigest()==a["sha256"]; assert d.count(b"### O1") == 1; print(a["slot"],"hash/bytes match")
print("RESULT JSON parsed; bookkeeping, not correctness validation",len(b),hashlib.sha256(b).hexdigest())'
